function LadderStruggleMainDialog:OnInitialize()
    ---@type Engine.Lib.CoWait
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        local params = self.controller.Argument.parameters
        if isNotNull(params) and isNotNull(params.systemName) then
            self:SetSystem(params.systemName)
        end
        self:InitComponent()

        local opList = {}
        -- 请求home页面
        table.insert(opList, self:RequestUpdate())

        -- home页面是否需要刷新挑战者的判断
        if self.component:EnterHomeNeedRefresh() then
            table.insert(opList, self:RequestRankInfoList(true))
            self.component:StartEnterHomeRefreshCoolDown()
        end

        -- 等待请求全部完成
        local opCount = #opList
        while true do
            local succeesCount = 0
            for i, v in ipairs(opList) do
                if v.succees == true then
                    succeesCount = succeesCount + 1
                end
            end
            if succeesCount == opCount then
                break
            end
            cs_coroutine.yield_return()
        end
    end))
    return coWait
end

