function LadderStruggleMainDialog:InitComponent()
    SetButtonAction(self.Btn_Record, Bind(self, self.OnRecordBtn))
    SetButtonAction(self.Btn_Shop, Bind(self, self.OnShopBtn))
    SetButtonAction(self.Btn_Rank, Bind(self, self.OnRankBtn))
