    local param4 = CfUtils.GetCfVo(self.component.settingIdParamVo, ParamVo, 4)
    local param5 = CfUtils.GetCfVo(self.component.settingIdParamVo, ParamVo, 5)
    local p1 = parse_strings(param1.num)

    ChallengeListNum = checkInt(p1[1]) + checkInt(p1[2]) + 1
    MyselfChallengeListIndex = checkInt(p1[2]) + 1
    RefreshBtnTime = checkInt(param4.num)
    AutoRefreshTime = checkInt(param5.num)

    if isNull(self.LB_RankCard.Env) then
        self.LB_RankCard:Init()
    end
    if isNull(self.LB_DailyReward.Env) then
        self.LB_DailyReward:Init()
    end

    -- 修改home页面的背景
    local bgNode = self.controller.transform:Find("BgNode/ImgBg")
    if isNotNull(bgNode) then
        local AImg = bgNode.gameObject:GetComponent(typeof(RawImageAlterable))
        if isNotNull(AImg) then
