function LadderStruggleMainDialog:LoopModeFreshChallengeCellList(maxNum)
    if not self.LoopListView.IsListViewInit then
        self.LoopListView:InitListView(maxNum, Bind(self, self.OnGetItemByIndex))
        self.LoopListView:UpdateDisplayItemCount("Cell")
    else
        GameUtils.ReloadData(self.LoopListView, maxNum)
    end
end

function LadderStruggleMainDialog:RefreshLoopListView(showAnim)
    self.loopListViewShowAnim = showAnim
    self:LoopModeFreshChallengeCellList(math.min(ChallengeListNum, #self.rankInfoList))
end

function LadderStruggleMainDialog:OnGetItemByIndex(loopListView, index)
    if index < 0 then
        return nil
    end

    local cell = loopListView:NewListViewItem("Cell")
    local LB_cell = GetLuaBehaviour(cell.gameObject, ChallengeCellLuaPath)
    if not cell.IsInitHandlerCalled then
        cell.IsInitHandlerCalled = true
        LB_cell:Init()
        LB_cell.Env:SetSystem(self.systemName)
    end
    local data = self.rankInfoList[index + 1]
    local LT_cell = LB_cell.Env
    -- print("[大乱斗] cell data", table.dump(data, nil, 5))
    LT_cell:UpdatePlayerInfo(self:ConvertData(data))

    if self.loopListViewShowAnim == true then
        -- 第一页的节点播放延迟出现的动画
        if index + 1 <= loopListView.DisplayItemCount then
            CfUtils.PlayDelayShowAnimation(cell, index)
        end
    end

    return cell
end

