--- 开始刷新按钮的倒计时
---@param remainTime any
function LadderStruggleMainDialog:StartRefreshBtnCoolDown(remainTime)
    if isNotNull(self.co_refreshBtn) then
        return
    end

    self.co_refreshBtn = cs_coroutine.start(function()
        self.refreshBtnTimer = remainTime
        while self.refreshBtnTimer > 0 do
            self.Txt_Refresh.text = string.format("%ds", self.refreshBtnTimer)
            cs_coroutine.yield_return(Yielders.GetWaitForSeconds(1))
            self.refreshBtnTimer = self.refreshBtnTimer - 1
            -- print("[大乱斗] 刷新计时", self.refreshBtnTimer)
        end
        self.Txt_Refresh.text = RefreshBtnText
        self.co_refreshBtn = nil
    end)
end

--- 刷新按钮
function LadderStruggleMainDialog:OnRefreshBtn()
    local remainTime = self.component:GetBtnRefreshTime()
    if remainTime > 0 then
        return
    end

    -- 刷新列表
    self:RequestRankInfoList(false, function()
        self:RefreshLoopListView(true)
        -- 重新计时
        self.component:StartRefreshBtnCoolDown()
        -- 刷新读秒
        self:StartRefreshBtnCoolDown(RefreshBtnTime)
    end)
end

