--- 请求主界面信息更新
function LadderStruggleMainDialog:RequestUpdate()
    local operator = {succees = false}
    GameUtils.Request(self.component.InterfaceHome, {}, function(request, response)
        if checkNumber(response.errCode) ~= 0 then
            return
        end
        operator.succees = true
        local jsonData = response.data
        local ticketNum = checkNumber(jsonData.ticket)
        local ticketRecoverTime = checkNumber(jsonData.lastCdTime)
        local myRank = checkNumber(jsonData.ranking)
        local myRankPercentage = checkNumber(jsonData.percentage)
        local battleTimes = checkNumber(jsonData.playerAsync.questTimes)
        local rankRewardState = checkNumber(jsonData.playerAsync.isDrawRanking)
        local dailyRewardState = checkNumber(jsonData.playerAsync.isDrawBox)
        local seasonRemainTime = checkNumber(jsonData.seasonRemainder)
        self.rankInfoList = self:RankInfoToList(jsonData.rankInfo)  -- 字典转数组
        -- print("[大乱斗] rankInfoList", table.dump(self.rankInfoList))
        self:RecordCurrentChallengerList(self.rankInfoList) -- 记录挑战者
        self:InsertMyselfRankInfo(self.rankInfoList, self:GetMyselfRankInfo(myRank))

        -- 设置rankCard
        self.LB_RankCard.Env:SetSystem(self.systemName)
        self.LB_RankCard.Env:SetPlayerRankInfo(myRank, myRankPercentage)
        self.LB_RankCard.Env:SetGetRewardBtn(myRank == 0 and 1 or rankRewardState + 1)
        self.LB_RankCard.Env:SetPlayerCombatValue(LadderStruggleUtils.GetMyStruggleCombatValue(self.component.questId))
        self.LB_RankCard.Env:SetSeasonEndTime(seasonRemainTime)

        -- 设置每日宝箱
        self.LB_DailyReward.Env:InitComponent(self.systemName)
        self.LB_DailyReward.Env:UpdateBattleNum(battleTimes)
        self.LB_DailyReward.Env:SetButtonState(dailyRewardState + 1)

        -- 设置门票
        self.component:UpdateTicketData(ticketNum, ticketRecoverTime)

        self.component:OnMyRankRefresh(checkInt(myRank))
    end)

    return operator
end

--- 请求刷新列表
function LadderStruggleMainDialog:RequestRankInfoList(needWait, callback)
    local operator = {succees = false}
    GameUtils.Request(self.component.InterfaceRefreshChallenger, {}, function(request, response)
        if checkNumber(response.errCode) ~= 0 then
            return
        end
        operator.succees = true
        local jsonData = response.data
        local rankInfo = jsonData.rankInfo
        local myRank = jsonData.myPlayerRanking
        local percentage = jsonData.percentage
        self.rankInfoList = self:RankInfoToList(rankInfo)
        self:RecordCurrentChallengerList(self.rankInfoList)
        self:InsertMyselfRankInfo(self.rankInfoList, self:GetMyselfRankInfo(myRank))
        -- 刷新rankCard
        self.LB_RankCard.Env:SetPlayerRankInfo(myRank, percentage)

        if isNotNull(callback) then
            callback()
        end

        self.component:OnMyRankRefresh(checkInt(myRank))
    end)

    return operator
end

--- 请求刷新当前的挑战者信息
function LadderStruggleMainDialog:RequestRankInfoListOnlyRank()
    if isNull(self.curChallengerList) or table.count(self.curChallengerList) <= 0 then
        printError("[异步PVP] 好像没有机器人")
        GameUtils.Toast("[异步PVP] 好像没有机器人")
        return
    end
    local succeed = false
    GameUtils.Request(self.component.InterfaceRefreshChallengerRank, {playerIds = table.concat(self.curChallengerList, ',')}, function(request, response)
        if checkNumber(response.errCode) ~= 0 then
            return
        end
        succeed = true
        local jsonData = response.data
        local rankInfo = jsonData.rankingInfo
        local myRank = jsonData.myPlayerRanking
        local percentage = jsonData.percentage
        self:UpdateCurrentChallengerRank(rankInfo)
        -- 刷新rankCard
        self.LB_RankCard.Env:SetPlayerRankInfo(myRank, percentage)

        self.component:OnMyRankRefresh(checkInt(myRank))
    end)
    while not succeed do
        cs_coroutine.yield_return()
    end
end

--- 构造我自己的rank信息
---@param rank any
function LadderStruggleMainDialog:GetMyselfRankInfo(rank)
    local playerComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.PlayerComponent)
    ---@type PlayerDojo
    local playerDojo = playerComponent:GetPlayerDojo()

    local myRankInfo = {}
    myRankInfo.playerId = playerDojo.playerId
    myRankInfo.name = playerDojo.playerName
    myRankInfo.level = playerDojo.level
    myRankInfo.avatar = playerDojo.playerAvatar
    myRankInfo.avatarFrame = playerDojo.playerAvatarFrame
    myRankInfo.ranking = rank
    myRankInfo.combatValue = LadderStruggleUtils.GetMyStruggleCombatValue(self.component.questId)
    myRankInfo.isMyself = true

    return myRankInfo
end

--- 把服务器数据格式，转换为cell需要的格式
---@param data any
function LadderStruggleMainDialog:ConvertData(data)
    if isNull(data) then
        return
    end

    if not IsNull(data.converted) then
        return data
    end

    if not isNull(data.team) then
        local team = {}

        for index, teamInfo in pairs(data.team) do
            team[checkInt(index)] = teamInfo
        end

        data.team = team
    end
    
    data.converted = 1

    return data
end

--- 把服务器返回的rank信息字典转换为数组
---@param rankInfoDict any
function LadderStruggleMainDialog:RankInfoToList(rankInfoDict)
    local rankInfoList = {}
    for playerId, rankInfo in pairs(rankInfoDict) do
        table.insert(rankInfoList, rankInfo)
    end

    table.sort(rankInfoList, function(a,b)
        return a.ranking < b.ranking
    end)
    return rankInfoList
end

--- 服务器返回挑战者排名，刷新排名
---@param rankList any
function LadderStruggleMainDialog:UpdateCurrentChallengerRank(rankList)
    for i, v in ipairs(self.rankInfoList) do
        local id = tostring(v.playerId)
        local rank = rankList[id]
        if not isNull(rank) then
            v.ranking = rank
        end
    end

    table.sort(self.rankInfoList, function(a,b)
        return a.ranking < b.ranking
    end)
end

--- 记录当前挑战者的列表
---@param rankInfoList any
function LadderStruggleMainDialog:RecordCurrentChallengerList(rankInfoList)
    self.curChallengerList = {}
    for playerId, rankInfo in pairs(rankInfoList) do
        table.insert(self.curChallengerList, rankInfo.playerId)
    end
end

--- 把我自己的rank信息插入到rank信息列表中
---@param rankInfoList any
---@param myRankInfo any
function LadderStruggleMainDialog:InsertMyselfRankInfo(rankInfoList, myRankInfo)
    if myRankInfo.ranking == 0 then
        return
    end
    local index = 1
    for i, rankInfo in ipairs(rankInfoList) do
        if myRankInfo.ranking > rankInfo.ranking then
            index = i + 1
        end
    end
    table.insert(rankInfoList, index, myRankInfo)
end

--- 刷新挑战者列表里我的战斗力
function LadderStruggleMainDialog:RefreshMySelfCombatValueInChallengerList()
    local newCombatValue = LadderStruggleUtils.GetMyStruggleCombatValue(self.component.questId)
    local myPlayerId = checkNumber(GameUtils.GetPlayerId())
    for i, v in ipairs(self.rankInfoList) do
        if checkNumber(v.playerId) == myPlayerId then
            v.combatValue = newCombatValue
        end
    end

    local count = self.LoopListView.ShownItemCount
    for i = 0, count - 1, 1 do
        local item = self.LoopListView:GetShownItemByIndex(i)
        if isNotNull(item) then
            local LB_cell = GetLuaBehaviour(item.gameObject, ChallengeCellLuaPath)
            if checkNumber(LB_cell.Env:GetPlayerId()) == myPlayerId then
                LB_cell.Env:UpdateCombatValue(newCombatValue)
            end
        end
    end
end

--- 刷新一下需要刷新的内容
function LadderStruggleMainDialog:RefreshSomeInfo()
    -- 是否有新的战报记录
    local imgNew = self.Btn_Record.transform:Find("ImgNew")
    KTool.SetActive(imgNew, self.component:HasNewRecord())

    -- 新排名动画
    if self.component:HasNewRank() then
        self.LB_RankCard.Env:PlayerRankChangeAnimation()
        self.component:SetNewRankState(0)   -- 清除新排名的标记
    end

    -- 刷新rankCard的战力
    self.LB_RankCard.Env:SetPlayerCombatValue(LadderStruggleUtils.GetMyStruggleCombatValue(self.component.questId))

    -- 刷新挑战者列表里我的战力
    self:RefreshMySelfCombatValueInChallengerList()
end

return LadderStruggleMainDialog


